import{NextResponse}from'next/server';import{createClient}from'@/lib/supabase/server';import{jsonSecurityHeaders,isAllowedOrigin}from'@/lib/security';import{readBoundedText}from'@/lib/security/request';export async function POST(request:Request){if(!isAllowedOrigin(request))return new NextResponse(null,{status:403,headers:jsonSecurityHeaders()});try{const body=JSON.parse(await readBoundedText(request)),referenceId=String(body?.referenceId||''),mode=body?.mode==='maximum'?'maximum':'standard',format=typeof body?.format==='string'?body.format.slice(0,20):null,fileSize=Number.isSafeInteger(body?.fileSize)?body.fileSize:null;if(!/^[A-Za-z0-9_-]{8,100}$/.test(referenceId))return NextResponse.json({error:'Invalid reference id'},{status:400,headers:jsonSecurityHeaders()});const s=await createClient(),{data:{user}}=await s.auth.getUser();if(!user)return NextResponse.json({error:'Authentication required'},{status:401,headers:jsonSecurityHeaders()});const{data,error}=await s.rpc('complete_cleaning',{p_user_id:user.id,p_reference_id:referenceId,p_mode:mode,p_format:format,p_file_size_bytes:fileSize});if(error){const no=error.message.includes('NO_ENTITLEMENT');return NextResponse.json({error:no?'No free cleaning or paid credit available.':'Unable to record cleaning'},{status:no?402:500,headers:jsonSecurityHeaders()});}return NextResponse.json(data,{headers:jsonSecurityHeaders()});}catch(e){const status=e instanceof Error&&e.message==='REQUEST_TOO_LARGE'?413:400;return NextResponse.json({error:status===413?'Request too large':'Invalid request'},{status,headers:jsonSecurityHeaders()});}}
